#define CL_TARGET_OPENCL_VERSION 120
#include <CL/cl.h>
#include <stdio.h>

const char *kernel_src = ""
"__kernel void vec_add(__global float* a, __global float* b, __global float* c) {"
"    int i = get_global_id(0);"
"    c[i] = a[i] + b[i];"
"}";

int main() {
    // Get platform and device
    cl_platform_id platform;
    cl_device_id device;
    clGetPlatformIDs(1, &platform, NULL);
    clGetDeviceIDs(platform, CL_DEVICE_TYPE_GPU, 1, &device, NULL);

    // Create context and command queue
    cl_context ctx = clCreateContext(NULL, 1, &device, NULL, NULL, NULL);
    cl_command_queue queue = clCreateCommandQueue(ctx, device, 0, NULL);

    // Build program
    cl_program program = clCreateProgramWithSource(ctx, 1, &kernel_src, NULL, NULL);
    clBuildProgram(program, 1, &device, NULL, NULL, NULL);
    cl_kernel kernel = clCreateKernel(program, "vec_add", NULL);

    // Create buffers and set args
    int n = 1024;
    cl_mem buf_a = clCreateBuffer(ctx, CL_MEM_READ_ONLY, n*sizeof(float), NULL, NULL);
    cl_mem buf_c = clCreateBuffer(ctx, CL_MEM_WRITE_ONLY, n*sizeof(float), NULL, NULL);
    clSetKernelArg(kernel, 0, sizeof(cl_mem), &buf_a);
    clSetKernelArg(kernel, 2, sizeof(cl_mem), &buf_c);

    // Launch kernel
    size_t global_size = n;
    clEnqueueNDRangeKernel(queue, kernel, 1, NULL, &global_size, NULL, 0, NULL, NULL);

    // Read result
    float result[1024];
    clEnqueueReadBuffer(queue, buf_c, CL_TRUE, 0, n*sizeof(float), result, 0, NULL, NULL);

    // Cleanup
    clReleaseMemObject(buf_a); clReleaseMemObject(buf_c);
    clReleaseKernel(kernel); clReleaseProgram(program);
    clReleaseCommandQueue(queue); clReleaseContext(ctx);
}
