// Memory types:
// __global  — device DRAM, slow, accessible by all work items
// __local   — shared memory within work group, fast
// __constant — read-only constant cache
// __private — registers, per work item, fastest

// Using local memory for a reduction kernel
__kernel void sum_reduction(
    __global float* input,
    __global float* output,
    __local  float* scratch,    // allocated per work group
    int n
) {
    int gid = get_global_id(0);
    int lid = get_local_id(0);
    int ls  = get_local_size(0);

    // Load into local memory
    scratch[lid] = (gid < n) ? input[gid] : 0.0f;
    barrier(CLK_LOCAL_MEM_FENCE);  // synchronize work group (like __syncthreads)

    // Reduction tree
    for (int s = ls/2; s > 0; s >>= 1) {
        if (lid < s) scratch[lid] += scratch[lid + s];
        barrier(CLK_LOCAL_MEM_FENCE);
    }
    if (lid == 0) output[get_group_id(0)] = scratch[0];
}
