int n = 1024;
float h_data[1024];  // host data

// Create buffer objects
cl_mem d_input = clCreateBuffer(ctx,
    CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR,  // copy host data immediately
    n * sizeof(float), h_data, NULL);

cl_mem d_output = clCreateBuffer(ctx,
    CL_MEM_WRITE_ONLY,
    n * sizeof(float), NULL, NULL);

// Transfer: host → device
clEnqueueWriteBuffer(queue, d_input,
    CL_TRUE,            // blocking
    0, n * sizeof(float), h_data,
    0, NULL, NULL);

// Non-blocking write
cl_event event;
clEnqueueWriteBuffer(queue, d_input, CL_FALSE, 0, n*sizeof(float), h_data, 0, NULL, &event);

// Transfer: device → host
float result[1024];
clEnqueueReadBuffer(queue, d_output,
    CL_TRUE,  // CL_TRUE = block until done
    0, n * sizeof(float), result,
    0, NULL, NULL);

// Zero out buffer
float zero = 0.0f;
clEnqueueFillBuffer(queue, d_output, &zero, sizeof(float), 0, n*sizeof(float), 0, NULL, NULL);

// Cleanup
clReleaseMemObject(d_input);
clReleaseMemObject(d_output);
