// Shared Virtual Memory (SVM) — pointers work on both host and device
// No explicit transfers needed!
void* svm_buf = clSVMAlloc(ctx,
    CL_MEM_READ_WRITE | CL_MEM_SVM_FINE_GRAIN_BUFFER,
    n * sizeof(float), 0);

// Fill on host
float* data = (float*)svm_buf;
for (int i = 0; i < n; i++) data[i] = i;

// Pass to kernel (no copy needed!)
clSetKernelArgSVMPointer(kernel, 0, svm_buf);
clEnqueueNDRangeKernel(queue, kernel, 1, NULL, &gs, NULL, 0, NULL, NULL);
clFinish(queue);

// Read directly on host (no transfer needed!)
for (int i = 0; i < 5; i++) printf("%.1f ", data[i]);

clSVMFree(ctx, svm_buf);

